<script setup>
import { computed, ref } from 'vue'; import { ArrowLeft, Plus } from 'lucide-vue-next'; import { useRoute, useRouter } from 'vue-router'; import { useAuthStore } from '@/stores/auth'; import { useInvoiceStore } from '@/stores/invoice'; import { usePaymentStore } from '@/stores/payment'; import { masterDataConfig } from '@/data/masterDataMock'; import { formatCurrency, formatDate } from '@/utils/formatters'; import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import PaymentModal from '@/components/payment/PaymentModal.vue'; import { useUiStore } from '@/stores/ui';
const route=useRoute(),router=useRouter(),auth=useAuthStore(),invoices=useInvoiceStore(),payments=usePaymentStore(),ui=useUiStore(),open=ref(false);const invoice=computed(()=>invoices.getInvoiceById(route.params.invoiceId));const summary=computed(()=>payments.paymentSummaryByInvoice(invoice.value));const history=computed(()=>invoice.value?payments.paymentsByInvoice(invoice.value.id):[]);const readOnly=computed(()=>auth.role==='manager');const account=(id)=>masterDataConfig.account.records.find(x=>x.id===id);const badge=s=>({belum_dibayar:['Belum Dibayar','neutral'],dibayar_sebagian:['Dibayar Sebagian','warning'],lunas:['Lunas','success'],jatuh_tempo:['Jatuh Tempo','danger']}[s]);const paid=()=>ui.notify('Pembayaran berhasil dicatat.');
</script>
<template><div v-if="invoice" class="p-6"><header class="mb-5 flex items-center gap-3"><button class="rounded p-1.5 text-[#667085] hover:bg-gray-100" aria-label="Kembali ke Billing" @click="router.push({name:'billing'})"><ArrowLeft :size="18"/></button><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-3"><h1 class="text-xl font-semibold text-[#172033]">{{invoice.number}}</h1><BaseBadge :variant="badge(summary.status)[1]">{{badge(summary.status)[0]}}</BaseBadge></div><p class="mt-0.5 text-sm text-[#667085]">{{invoice.client}} — {{invoice.name}}</p></div><BaseButton v-if="!readOnly&&summary.remaining>0&&invoice.status==='published'" @click="open=true"><Plus :size="14"/>Catat Pembayaran</BaseButton></header><div class="mb-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><BaseCard v-for="card in [{label:'Total Invoice',value:formatCurrency(summary.total),color:'#172033'},{label:'Sudah Dibayar',value:formatCurrency(summary.totalPaid),color:'#16A34A'},{label:'Sisa Tagihan',value:formatCurrency(summary.remaining),color:summary.remaining?'#D97706':'#16A34A'},{label:'Jatuh Tempo',value:formatDate(invoice.dueDate),color:summary.status==='jatuh_tempo'?'#DC2626':'#667085'}]" :key="card.label" padding="p-4"><p class="mb-2 text-xs text-[#667085]">{{card.label}}</p><p class="text-base font-bold" :style="{color:card.color}">{{card.value}}</p></BaseCard></div><BaseCard padding="p-0"><div class="border-b border-[#E2E6EC] px-5 py-4"><h2 class="text-sm font-semibold text-[#172033]">Riwayat Pembayaran</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[700px]"><thead><tr class="border-b border-[#E2E6EC] bg-[#F9FAFB]"><th v-for="h in ['Tanggal','Metode','Rekening','Nomor Referensi','Nominal']" :key="h" class="px-4 py-3 text-left text-xs font-medium text-[#667085] first:px-5 last:text-right">{{h}}</th></tr></thead><tbody><tr v-if="!history.length"><td colspan="5" class="px-5 py-8 text-center text-sm text-[#9CA3AF]">Belum ada pembayaran tercatat</td></tr><tr v-for="payment in history" :key="payment.id" class="border-b border-[#F3F4F6]"><td class="px-5 py-3 text-sm text-[#667085]">{{formatDate(payment.paymentDate)}}</td><td class="px-4 py-3 text-sm text-[#667085]">{{payment.method}}</td><td class="px-4 py-3 text-sm text-[#667085]">{{account(payment.accountId)?.nama||'-'}}</td><td class="px-4 py-3 font-mono text-xs text-[#667085]">{{payment.referenceNumber||'-'}}</td><td class="px-4 py-3 text-right text-sm font-semibold text-[#172033]">{{formatCurrency(payment.amount)}}</td></tr></tbody></table></div><div v-if="history.length" class="flex justify-between border-t border-[#E2E6EC] px-5 py-3"><span class="text-xs text-[#667085]">Total pembayaran</span><span class="text-sm font-bold text-green-600">{{formatCurrency(summary.totalPaid)}}</span></div></BaseCard><PaymentModal :open="open" :invoice="invoice" @close="open=false" @saved="paid"/></div><div v-else class="p-6 text-sm text-[#667085]">Billing tidak ditemukan.</div></template>
